#[cfg(test)]
mod tests {
    use super::*;

    /// The cheap gate: parse without elaborating.
    #[test]
    fn test_source_parses() {
        if let Err(e) = crate::test_utils::parse_check(SRC_WH3_STEP_STUCK_STABLE) {
            panic!("wh3_step_stuck_stable does not parse: {e}");
        }
    }

    /// The statement must be about wstuck STABILITY, not about the step being
    /// equal at consecutive budgets — the latter is false, because wstarved may
    /// move.
    #[test]
    fn test_states_stability_not_equality() {
        let s = SRC_WH3_STEP_STUCK_STABLE;
        assert!(
            s.contains("WhStepR.wstuck"),
            "the conclusion must be about the wstuck verdict"
        );
        assert!(
            s.matches("whnf_fuel_red_wh3").count() > 2,
            "it must be stated over the three-way loop, not the two-way one"
        );
    }
}
